// YouTube channel feeds are Atom: each entry carries a yt:videoId element and a
// link to the watch page. n8n's RSS trigger (rss-parser) exposes the namespaced
// field as `id` ("yt:video:VIDEO_ID") and the link as `link`; some versions also
// surface `yt:videoId`. Try the video id first, fall back to the link.
const out = [];
for (const item of $input.all()) {
  const j = item.json;
  const rawId = j['yt:videoId'] || j.videoId || '';
  const fromId = String(rawId).replace(/^yt:video:/, '').trim();
  const fromEntryId = String(j.id || '').startsWith('yt:video:')
    ? String(j.id).slice('yt:video:'.length).trim()
    : '';
  const videoId = fromId || fromEntryId;
  const videoUrl = videoId
    ? `https://www.youtube.com/watch?v=${videoId}`
    : (j.link || '');
  if (!videoUrl) continue; // entry has neither a video id nor a link
  out.push({
    json: {
      videoUrl,
      videoId: videoId || null,
      videoTitle: j.title || '',
      publishedAt: j.isoDate || j.pubDate || '',
    },
  });
}
return out;

// The Actor's dataset contains type:'transcript' rows (one per video with
// captions) and type:'error' rows for videos it could not transcribe — captions
// disabled, private/age-restricted, live stream without captions, bad URL.
// Error rows are never billed. Keep only the transcripts.
return $input.all().filter((item) => item.json.type === 'transcript');
